use anyhow :: { Context , Result } ; use std :: path :: { Path , PathBuf } ; use std :: fs ; use std :: process :: Command ; use std :: collections :: HashSet ; use super :: * ; use tempfile :: tempdir ; # [doc = " Onboard a new repository, crate, or workspace"] pub fn cmd_onboard (git_repo : Option < String > , crate_name : Option < String > , workdir : Option < PathBuf > , branch : String , workflow : String , output_dir : PathBuf ,) -> Result < () > { println ! ("🚀 Starting onboarding workflow: {}" , workflow) ; let source_count = git_repo . is_some () as u8 + crate_name . is_some () as u8 + workdir . is_some () as u8 ; if source_count != 1 { anyhow :: bail ! ("Exactly one of --git-repo, --crate, or --workdir must be specified") ; } let workspace_path = match (git_repo , crate_name , workdir) { (Some (repo) , None , None) => onboard_git_repo (& repo , & branch , & output_dir) ? , (None , Some (crate_name) , None) => onboard_crate (& crate_name , & output_dir) ? , (None , None , Some (workdir)) => { println ! ("📁 Using local workspace: {}" , workdir . display ()) ; workdir } _ => unreachable ! () , } ; run_onboarding_workflow (& workspace_path , & workflow , & output_dir) ? ; println ! ("✅ Onboarding complete!") ; println ! ("📁 Workspace: {}" , workspace_path . display ()) ; Ok (()) }